import "prismjs/components/prism-javascript";

function MyArtifactsPage() {
    const emojiMap = {
        js: "🟨",
        ts: "🔵",
        java: "☕",
        py: "🐍",
        c: "🟦",
        cpp: "💠",
        json: "📄",
        md: "📝",
        txt: "📃",
        css: "🎨",
        html: "🌐",
        yaml: "📦",
        yml: "📦",
        pdf: "📕",
        png: "🖼️",
        jpg: "🖼️",
        jpeg: "🖼️",
        unknown: "📁",
    };

    const [artifacts, setArtifacts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState("");
    const [filter, setFilter] = useState("all");

    // ⭐ PARTICLES (MY STUDIES PAGE İLE AYNI)
    const [particles, setParticles] = useState([]);

    const [previewArtifact, setPreviewArtifact] = useState(null);
    const [previewURL, setPreviewURL] = useState("");
    const [previewLoading, setPreviewLoading] = useState(false);
    const [previewText, setPreviewText] = useState("");
    const [previewLanguage, setPreviewLanguage] = useState("markup");

    const navigate = useNavigate();

    /* ================= PRISM ================= */
    useEffect(() => {
        if (previewText) Prism.highlightAll();
    }, [previewText]);

    /* ================= PARTICLES (YENİ SİSTEM) ================= */
    useEffect(() => {
        const generated = [...Array(55)].map(() => ({
            id: crypto.randomUUID(),
            left: Math.random() * 100,
            top: Math.random() * 100,
            delay: -(Math.random() * 15).toFixed(2),
            duration: 16 + Math.random() * 10,
        }));
        setParticles(generated);
    }, []);

    /* ================= PAGE SETUP ================= */
    useEffect(() => {
        document.body.style.margin = "0";
        document.body.style.padding = "0";
        document.documentElement.style.margin = "0";
        document.documentElement.style.padding = "0";
        document.body.style.backgroundColor = "black";
    }, []);

    /* ================= FETCH ARTIFACTS ================= */
    useEffect(() => {
        const fetchArtifacts = async () => {
            try {
                const token = localStorage.getItem("token");
                const response = await fetch("http://localhost:8080/api/artifacts/my-artifacts", {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: `Bearer ${token}`,
                    },
                });

                if (!response.ok) throw new Error("Failed to fetch artifacts");
                const data = await response.json();

                setArtifacts(data);
            } catch (error) {
                console.error("❌ Error fetching artifacts:", error);
            } finally {
                setLoading(false);
            }
        };

        fetchArtifacts();
    }, []);

    /* ================= EXT HELPERS ================= */
    const extractExtension = (filename) =>
        filename.includes(".") ? filename.split(".").pop().toLowerCase() : "unknown";

    const filtered = artifacts.filter((a) => {
        const ext = extractExtension(a.filename);
        const matchesSearch =
            a.filename.toLowerCase().includes(search.toLowerCase()) ||
            (a.tags || "").toLowerCase().includes(search.toLowerCase());
        const matchesFilter = filter === "all" || filter === ext;
        return matchesSearch && matchesFilter;
    });

    const fileTypes = ["all", ...new Set(artifacts.map((a) => extractExtension(a.filename)))];

    const capitalize = (s) =>
        s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

    /* ================= PREVIEW HANDLER ================= */
    const handlePreview = async (artifact) => {
        const token = localStorage.getItem("token");
        const url = `http://localhost:8080/researcher/artifact/${artifact.id}`;

        setPreviewArtifact(artifact);
        setPreviewLoading(true);
        setPreviewText("");
        setPreviewURL("");

        try {
            const response = await fetch(url, {
                headers: { Authorization: `Bearer ${token}` },
            });

            if (!response.ok) throw new Error("Failed to preview file");

            const blob = await response.blob();
            const blobURL = URL.createObjectURL(blob);
            const filename = artifact.filename.toLowerCase();

            if (filename.match(/\.(pdf|png|jpg|jpeg)$/i)) {
                setPreviewURL(blobURL);
            } else if (
                filename.match(
                    /\.(txt|json|java|py|js|md|html|css|ts|c|cpp|yaml|yml)$/i
                )
            ) {
                const ext = filename.split(".").pop();
                const langMap = {
                    java: "clike",
                    js: "javascript",
                    ts: "javascript",
                    c: "clike",
                    cpp: "clike",
                    json: "javascript",
                    md: "markup",
                    html: "markup",
                    css: "markup",
                    yaml: "markup",
                    yml: "markup",
                    txt: "markup",
                    py: "markup",
                };

                setPreviewLanguage(langMap[ext] || "markup");

                const text = await blob.text();
                setPreviewText(text);
            } else {
                setPreviewText("Preview not supported for this file type.");
            }
        } catch (error) {
            console.error("Preview error:", error);
            setPreviewText("Error loading preview.");
        } finally {
            setPreviewLoading(false);
        }
    };

    /* ================= RENDER ================= */
    return (
        <div style={styles.container}>

            {/* ⭐ PARTICLE BACKGROUND — MY STUDIES PAGE İLE AYNI */}
            <div style={styles.particles}>
                {particles.map((p) => (
                    <div
                        key={p.id}
                        style={{
                            ...styles.particle,
                            left: `${p.left}%`,
                            top: `${p.top}vh`,
                            animationDelay: `${p.delay}s`,
                            animationDuration: `${p.duration}s`,
                        }}
                    />
                ))}
            </div>

            {/* NAVBAR */}
            <div style={styles.navbar}>
                <h2 style={styles.title}>My Artifacts</h2>
                <div style={styles.right}>
                    <button
                        style={styles.profileButton}
                        onClick={() => navigate("/researcher")}
                    >
                        ← Back to Dashboard
                    </button>
                </div>
            </div>

            {/* MAIN CONTENT */}
            <div style={styles.mainContent}>
                <div style={{ textAlign: "center", marginBottom: "40px" }}>
                    <button
                        style={styles.uploadButton}
                        onMouseEnter={(e) => {
                            e.currentTarget.style.transform = "scale(1.06)";
                            e.currentTarget.style.background = "rgba(34,197,94,0.18)";
                        }}
                        onMouseLeave={(e) => {
                            e.currentTarget.style.transform = "scale(1)";
                            e.currentTarget.style.background = "rgba(34,197,94,0.1)";
                        }}
                        onClick={() => navigate("/upload-artifact")}
                    >
                        Upload New Artifact
                    </button>
                </div>

                <div style={styles.filterRow}>
                    <input
                        placeholder="Search by filename or tag..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        style={styles.searchBar}
                    />

                    <select
                        value={filter}
                        onChange={(e) => setFilter(e.target.value)}
                        style={styles.filterDropdown}
                    >
                        {fileTypes.map((ext, index) => (
                            <option key={index} value={ext}>
                                {ext === "all" ? "All File Types" : capitalize(ext)}
                            </option>
                        ))}
                    </select>
                </div>

                {loading ? (
                    <p style={styles.loading}>Loading artifacts...</p>
                ) : filtered.length === 0 ? (
                    <p style={styles.noData}>No artifacts found.</p>
                ) : (
                    <div style={styles.grid}>
                        {filtered.map((artifact) => {
                            const ext = extractExtension(artifact.filename);

                            return (
                                <div key={artifact.id} style={styles.card}>
                                    <div style={styles.cardHeader}>
                                        <span style={styles.emojiBadge}>
                                            {emojiMap[ext] || "📁"}
                                        </span>

                                        <h3 style={styles.filename}>{artifact.filename}</h3>

                                        <button
                                            style={styles.previewButton}
                                            onClick={() => handlePreview(artifact)}
                                        >
                                            <svg
                                                width="20"
                                                height="20"
                                                viewBox="0 0 24 24"
                                                fill="none"
                                                stroke="#60a5fa"
                                                strokeWidth="2"
                                                strokeLinecap="round"
                                                strokeLinejoin="round"
                                                style={{
                                                    display: "block",
                                                    transition: "transform 0.2s ease",
                                                }}
                                            >
                                                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                                                <circle cx="12" cy="12" r="3"></circle>
                                            </svg>
                                        </button>
                                    </div>

                                    {/* ⭐ CATEGORY + TAG BADGES (tek tag, tek category) */}
                                    <div style={styles.badgeRow}>
                                        <span style={styles.categoryBadge}>
                                            {artifact.category || "No Category"}
                                        </span>

                                        <span style={styles.tagBadge}>
                                            {artifact.tags || "No Tag"}
                                        </span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* ======================= PREVIEW MODAL ======================= */}
            {previewArtifact && (
                <div style={styles.modalOverlay} onClick={() => setPreviewArtifact(null)}>
                    <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
                        <h2 style={styles.previewTitle}>{previewArtifact.filename}</h2>

                        {previewLoading ? (
                            <p style={{ color: "#93c5fd" }}>Loading preview...</p>
                        ) : (
                            <>
                                {/* PDF */}
                                {previewURL && previewArtifact.filename.endsWith(".pdf") && (
                                    <embed
                                        src={previewURL}
                                        type="application/pdf"
                                        style={{
                                            width: "100%",
                                            height: "70vh",
                                            borderRadius: "12px",
                                            background: "white",
                                        }}
                                    />
                                )}

                                {/* IMAGE */}
                                {previewURL &&
                                    previewArtifact.filename.match(/\.(png|jpg|jpeg)$/i) && (
                                        <img
                                            src={previewURL}
                                            alt="preview"
                                            style={{
                                                maxWidth: "100%",
                                                maxHeight: "70vh",
                                                borderRadius: "12px",
                                            }}
                                        />
                                    )}

                                {/* TEXT */}
                                {previewText && (
                                    <pre
                                        style={{
                                            background: "#0f172a",
                                            color: "#e2e8f0",
                                            padding: "20px",
                                            borderRadius: "12px",
                                            maxHeight: "70vh",
                                            overflowY: "auto",
                                            textAlign: "left",
                                        }}
                                    >
                                        <code className={`language-${previewLanguage}`}>
                                            {previewText}
                                        </code>
                                    </pre>
                                )}
                            </>
                        )}

                        <button
                            style={styles.closeButton}
                            onClick={() => setPreviewArtifact(null)}
                        >
                            Close
                        </button>
                    </div>
                </div>
            )}

            <style>{`
                @keyframes floatParticle {
                    0% { transform: translateY(0); opacity: 0.4; }
                    50% { opacity: 1; }
                    100% { transform: translateY(-120vh); opacity: 0; }
                }
            `}</style>
        </div>
    );
}

